class Solution:
    def __init__(self):
        self.buf4 = [''] * 4
        self.buf_ptr = 0
        self.buf_cnt = 0

    def read(self, buf, n):
        total = 0
        while total < n:
            if self.buf_ptr == self.buf_cnt:
                self.buf_cnt = read4(self.buf4)
                self.buf_ptr = 0
            if self.buf_cnt == 0:
                break
            while total < n and self.buf_ptr < self.buf_cnt:
                buf[total] = self.buf4[self.buf_ptr]
                total += 1
                self.buf_ptr += 1
        return total

class Solution:
    def lengthOfLongestSubstringTwoDistinct(self, s: str) -> int:
        from collections import defaultdict
        count = defaultdict(int)
        left = res = 0
        for right in range(len(s)):
            count[s[right]] += 1
            while len(count) > 2:
                count[s[left]] -= 1
                if count[s[left]] == 0:
                    del count[s[left]]
                left += 1
            res = max(res, right - left + 1)
        return res

class Solution:
    def isOneEditDistance(self, s: str, t: str) -> bool:
        m, n = len(s), len(t)
        if abs(m - n) > 1:
            return False
        if m > n:
            return self.isOneEditDistance(t, s)
        for i in range(m):
            if s[i] != t[i]:
                if m == n:
                    return s[i+1:] == t[i+1:]
                else:
                    return s[i:] == t[i+1:]
        return m + 1 == n

