class Solution:
    def majorityElement(self, nums: list[int]) -> list[int]:
        c1 = c2 = 0
        r1 = r2 = None
        for n in nums:
            if r1 is not None and n == r1:
                c1 += 1
            elif r2 is not None and n == r2:
                c2 += 1
            elif c1 == 0:
                r1, c1 = n, 1
            elif c2 == 0:
                r2, c2 = n, 1
            else:
                c1 -= 1; c2 -= 1
        return [x for x in (r1, r2) if x is not None and nums.count(x) > len(nums)//3]

