class Solution:
    def findStrobogrammatic(self, n: int) -> list[str]:
        def helper(cur_len, total_len):
            if cur_len == 0:
                return ['']
            if cur_len == 1:
                return ['0', '1', '8']
            middles = helper(cur_len - 2, total_len)
            res = []
            for m in middles:
                for a, b in [('0','0'),('1','1'),('6','9'),('8','8'),('9','6')]:
                    if a == '0' and cur_len == total_len:
                        continue
                    res.append(a + m + b)
            return res
        return helper(n, n)

class Solution:
    def strobogrammaticInRange(self, low: str, high: str) -> int:
        def helper(cur_len, total_len):
            if cur_len == 0: return ['']
            if cur_len == 1: return ['0','1','8']
            middles = helper(cur_len-2, total_len)
            res = []
            for m in middles:
                for a,b in [('0','0'),('1','1'),('6','9'),('8','8'),('9','6')]:
                    if a=='0' and cur_len==total_len: continue
                    res.append(a+m+b)
            return res
        count = 0
        for length in range(len(low), len(high)+1):
            nums = helper(length, length)
            for num in nums:
                if len(num) == len(low) and num < low: continue
                if len(num) == len(high) and num > high: continue
                count += 1
        return count

