class Solution:
    def countUnivalSubtrees(self, root: TreeNode) -> int:
        self.count = 0
        def dfs(node):
            if not node:
                return True
            left = dfs(node.left)
            right = dfs(node.right)
            if left and right:
                if node.left and node.left.val != node.val:
                    return False
                if node.right and node.right.val != node.val:
