class Solution:
    def getFactors(self, n: int) -> list[list[int]]:
        res = []
        def backtrack(start, target, path):
            for i in range(start, int(target**0.5)+1):
                if target % i == 0:
                    path.append(i)
                    res.append(path + [target//i])
                    backtrack(i, target//i, path)
