class Codec:
    def encode(self, strs: list[str]) -> str:
        return ''.join(f'{len(s)}#{s}' for s in strs)

    def decode(self, s: str) -> list[str]:
        res = []
        i = 0
        while i < len(s):
            j = s.index('#', i)
            length = int(s[i:j])
            res.append(s[j+1:j+1+length])
            i = j + 1 + length
        return res

class Solution:
    def closestKValues(self, root: TreeNode, target: float, k: int) -> list[int]:
        from collections import deque
        dq = deque()
        def inorder(node):
            if not node:
                return
            inorder(node.left)
            if len(dq) == k:
                if abs(node.val - target) >= abs(dq[0] - target):
                    return
                dq.popleft()
            dq.append(node.val)
            inorder(node.right)
        inorder(root)
        return list(dq)

class Solution:
    def numberToWords(self, num: int) -> str:
        if num == 0:
            return 'Zero'
        ones = ['','One','Two','Three','Four','Five','Six','Seven','Eight','Nine',
                'Ten','Eleven','Twelve','Thirteen','Fourteen','Fifteen','Sixteen',
                'Seventeen','Eighteen','Nineteen']
        tens = ['','','Twenty','Thirty','Forty','Fifty','Sixty','Seventy','Eighty','Ninety']
        def helper(n):
            if n == 0: return ''
            elif n < 20: return ones[n] + ' '
            elif n < 100: return tens[n//10] + ' ' + helper(n%10)
            else: return ones[n//100] + ' Hundred ' + helper(n%100)
        res = ''
        for val, word in [(1000000000,'Billion'),(1000000,'Million'),(1000,'Thousand')]:
            if num >= val:
                res += helper(num//val) + word + ' '
                num %= val
        res += helper(num)
        return res.strip()

