class ZigzagIterator:
    def __init__(self, v1: list[int], v2: list[int]):
        from collections import deque
        self.q = deque()
        if v1: self.q.append(iter(v1))
        if v2: self.q.append(iter(v2))
        self.val = None

    def next(self) -> int:
        return self.val

    def hasNext(self) -> bool:
        while self.q:
            it = self.q.popleft()
            try:
                self.val = next(it)
                self.q.append(it)
                return True
            except StopIteration:
                continue
        return False

class Solution:
    def addOperators(self, num: str, target: int) -> list[str]:
        res = []
        def backtrack(idx, path, val, prev):
            if idx == len(num):
                if val == target:
                    res.append(path)
                return
            for i in range(idx, len(num)):
                if i > idx and num[idx] == '0':
                    break
                cur = int(num[idx:i+1])
                if idx == 0:
                    backtrack(i+1, str(cur), cur, cur)
                else:
                    backtrack(i+1, path+'+'+str(cur), val+cur, cur)
                    backtrack(i+1, path+'-'+str(cur), val-cur, -cur)
                    backtrack(i+1, path+'*'+str(cur), val-prev+prev*cur, prev*cur)
        backtrack(0, '', 0, 0)
        return res

class PeekingIterator:
    def __init__(self, iterator):
        self.it = iterator
        self.peeked = None
        self.has_peeked = False

    def peek(self):
        if not self.has_peeked:
            self.peeked = self.it.next()
            self.has_peeked = True
        return self.peeked

    def next(self):
        if self.has_peeked:
            self.has_peeked = False
            return self.peeked
        return self.it.next()

    def hasNext(self):
        return self.has_peeked or self.it.hasNext()

class Solution:
    def wallsAndGates(self, rooms: list[list[int]]) -> None:
        from collections import deque
        if not rooms:
            return
        m, n = len(rooms), len(rooms[0])
        INF = 2147483647
        q = deque()
        for i in range(m):
            for j in range(n):
                if rooms[i][j] == 0:
                    q.append((i, j))
        while q:
            x, y = q.popleft()
            for dx, dy in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx, ny = x+dx, y+dy
                if 0<=nx<m and 0<=ny<n and rooms[nx][ny] == INF:
                    rooms[nx][ny] = rooms[x][y] + 1
                    q.append((nx, ny))

class ValidWordAbbr:
    def __init__(self, dictionary: list[str]):
        self.abbr_map = {}
        for word in set(dictionary):
            a = self._abbr(word)
            if a in self.abbr_map:
                self.abbr_map[a] = ''
            else:
                self.abbr_map[a] = word

    def _abbr(self, word):
        if len(word) <= 2:
            return word
        return word[0] + str(len(word)-2) + word[-1]

    def isUnique(self, word: str) -> bool:
        a = self._abbr(word)
        return a not in self.abbr_map or self.abbr_map[a] == word

class Solution:
    def wordPattern(self, pattern: str, s: str) -> bool:
        words = s.split()
        if len(pattern) != len(words):
            return False
        p2w, w2p = {}, {}
        for p, w in zip(pattern, words):
            if p in p2w and p2w[p] != w:
                return False
            if w in w2p and w2p[w] != p:
                return False
            p2w[p] = w
            w2p[w] = p
        return True

class Solution:
    def wordPatternMatch(self, pattern: str, s: str) -> bool:
        def backtrack(pi, si, p2s, s2p):
            if pi == len(pattern) and si == len(s):
                return True
            if pi == len(pattern) or si == len(s):
                return False
            p = pattern[pi]
            if p in p2s:
                word = p2s[p]
                if not s[si:].startswith(word):
                    return False
                return backtrack(pi+1, si+len(word), p2s, s2p)
            for end in range(si+1, len(s)+1):
                word = s[si:end]
                if word in s2p:
                    continue
                p2s[p] = word
                s2p[word] = p
                if backtrack(pi+1, end, p2s, s2p):
                    return True
                del p2s[p]
                del s2p[word]
            return False
        return backtrack(0, 0, {}, {})

